@extends('layouts.app') @section('content')<div class="page-header"><div><h1>Disponibilidade</h1><p>{{ $eventType->name }}</p></div></div>@include('scheduling.admin.nav')<div class="detail-grid"><section class="panel"><h2>Disponibilidade semanal</h2>@forelse($rules as $rule)<div class="availability-row"><span>{{ [1=>'SEG',2=>'TER',3=>'QUA',4=>'QUI',5=>'SEX',6=>'SÁB',7=>'DOM'][$rule->day_of_week] }}</span><strong>{{ substr($rule->start_time,0,5) }} — {{ substr($rule->end_time,0,5) }}</strong><small>{{ $rule->timezone }}</small>@if(auth()->user()->canOperate())<form method="post" action="{{ route('scheduling.admin.rules.delete',[$eventType,$rule]) }}">@csrf @method('DELETE')<button class="link-danger" aria-label="Remover janela">Remover</button></form>@endif</div>@empty<p class="empty-state">Nenhuma disponibilidade padrão.</p>@endforelse @if(auth()->user()->canOperate())<form method="post" action="{{ route('scheduling.admin.rules.store',$eventType) }}" class="form-grid">@csrf<label>Dia<select name="day_of_week">@foreach([1=>'SEG',2=>'TER',3=>'QUA',4=>'QUI',5=>'SEX',6=>'SÁB',7=>'DOM'] as $v=>$l)<option value="{{ $v }}">{{ $l }}</option>@endforeach</select></label><label>Início<input type="time" name="start_time" required></label><label>Fim<input type="time" name="end_time" required></label><label>Timezone<input name="timezone" value="{{ config('scheduling.default_timezone') }}" required></label><button class="button">Adicionar janela</button></form>@endif</section><section class="panel"><h2>Exceções</h2>@forelse($exceptions as $exception)<div class="availability-row"><span>{{ $exception->date->format('d/m/Y') }}</span><strong>{{ $exception->type==='unavailable'?'Bloqueado':'Disponível' }}</strong><small>{{ $exception->reason }}</small></div>@empty<p class="empty-state">Nenhuma exceção cadastrada.</p>@endforelse @if(auth()->user()->canOperate())<form method="post" action="{{ route('scheduling.admin.exceptions.store',$eventType) }}" class="form-grid">@csrf<label>Data<inp